// Package envoy writes the Envoy configuration of a gateway: it fills the embedded fragments, splices them into one
// YAML tree and encodes that tree.
package envoy

import (
	"bytes"
	"embed"
	"errors"
	"fmt"
	"net"
	"slices"
	"strconv"
	"strings"
	"text/template"

	"go.yaml.in/yaml/v3"

	"github.com/kitecorp/proxyfile/v2/internal/model"
	"github.com/kitecorp/proxyfile/v2/internal/origins"
	"github.com/kitecorp/proxyfile/v2/internal/quote"
	"github.com/kitecorp/proxyfile/v2/internal/rpc"
)

// Input is everything the generated file is made from.
type Input struct {
	Gateway *model.Gateway
	Origins *origins.File
	RPC     []rpc.Route // sorted by path; nil without an rpc entry
}

// fragments holds one YAML document per part of the file, each a text/template. A plain scalar $name as a mapping
// value marks where the node built for that name goes.
//
//go:embed fragments
var fragments embed.FS

// header is line 1 of every generated file. It names no input and no version, so the bytes depend on the model
// alone.
const header = "# Generated by proxyfile. Do not edit: change the proxyfile beside it and run proxyfile render; " +
	"proxyfile check fails on a hand edit.\n"

// connectStatus is the Lua filter's script. It lives in a file of its own, so it reads as Lua and is never retyped
// inside YAML.
//
//go:embed fragments/connect-status.lua
var connectStatus string

// The filters, in order: set_metadata, the header mutation (Vary on every answer, and each RPC route's question for the
// check), the RBAC refusal of a foreign browser origin, CORS, the rate limit (with a rate_limit), the token filter
// (with auth.jwt), ext_authz (with auth.ask), the Lua filter that corrects the status of the bridge's errors and the
// Connect-gRPC bridge (both with envoy.connect_bridge), the router. A foreign origin is refused before ext_authz could
// call the check; a browser's preflight carries no authorization, because it sends only the names of the request's own
// headers (the Fetch standard, "CORS-preflight fetch"), and it is answered before the token filter and ext_authz in
// any case. A request over a limit is refused before its token is verified and before ext_authz could call the check,
// and a token is verified before the check is asked (measured on Envoy 1.40.2); the limit also runs before the bridge,
// which removes the connect-protocol-version header the Connect answer to it is matched on
// (connect_grpc_bridge/filter.cc).
var httpFilters = []struct {
	fragment string
	present  func(g *model.Gateway) bool // whether a gateway has the filter
}{
	{"filter-set-metadata.yaml", hasAuth},
	{"filter-header-mutation.yaml", always},
	{"filter-rbac.yaml", always},
	{"filter-cors.yaml", always},
	{"filter-local-ratelimit.yaml", hasRateLimit},
	{"filter-jwt-authn.yaml", hasJWT},
	{"filter-ext-authz.yaml", hasAuth},
	{"filter-lua.yaml", hasBridge},
	{"filter-connect-bridge.yaml", hasBridge},
	{"filter-router.yaml", always},
}

func always(*model.Gateway) bool { return true }

// hasAuth says whether the gateway asks a service about each request, auth.ask, which set_metadata, ext_authz and
// their log line serve; hasJWT whether it verifies a token itself, auth.jwt.
func hasAuth(g *model.Gateway) bool { return g.Auth != nil }

func hasJWT(g *model.Gateway) bool { return g.JWT != nil }

func hasRPC(g *model.Gateway) bool { return g.RPCEntry() != nil }

// hasRateLimit says whether a route or the rpc entry has a limit, which the rate limit filter and the Connect answer to
// a limited call serve.
func hasRateLimit(g *model.Gateway) bool { return len(buckets(g)) > 0 }

// hasBridge says whether the RPC routes take Connect calls, which the bridge and its Lua status filter serve.
func hasBridge(g *model.Gateway) bool { return hasRPC(g) && g.Envoy.ConnectBridge }

// Generate returns the whole envoy.yaml. Its error means a fragment did not fill or parse: a bug, never a problem
// in the input, which earlier stages have refused.
func Generate(in Input) ([]byte, error) {
	g := in.Gateway
	var b builder
	var clusters []*yaml.Node
	for _, service := range g.Services {
		for _, port := range service.Ports {
			clusters = append(clusters, b.fill("cluster.yaml", cluster(g, service, port)))
		}
	}
	// The OpenTelemetry tracer sends its spans over gRPC to a cluster, so the collector is one more cluster, after the
	// services'.
	if g.Tracing != nil && g.Tracing.OTel != nil {
		otel := g.Tracing.OTel
		clusters = append(clusters, b.fill("cluster.yaml", extraCluster(g, otelCluster, otel.Host, otel.Port, otel.DNS, true)))
	}
	// The token filter fetches a keys URL through a cluster too, after the collector's.
	if g.JWT != nil && g.JWT.URL != "" {
		clusters = append(clusters, b.fill("cluster.yaml", keysCluster(g)))
	}
	// Every virtual host holds the same routes, so they share one node, which the encoder writes out in full at each
	// place.
	sharedRoutes := sequence(b.routes(in)...)
	var virtualHosts []*yaml.Node
	for _, environment := range in.Origins.Environments {
		virtualHosts = append(virtualHosts,
			b.fill("virtual-host.yaml", virtualHost(environment, in.Origins.CORS), splice{"routes", sharedRoutes}))
	}
	filterValues := data{"Namespace": g.Envoy.Namespace, "Check": check(g), "JWT": jwt(g), "Script": connectStatus,
		"RateLimitNamespace": rateLimitNamespace(g.Envoy.Namespace), "Buckets": buckets(g)}
	var filters []*yaml.Node
	for _, filter := range httpFilters {
		if filter.present(g) {
			filters = append(filters, b.fill(filter.fragment, filterValues))
		}
	}
	logs := []*yaml.Node{
		b.fill("log-request.yaml", data{"Log": g.Log, "Auth": g.Auth != nil}),
		b.fill("log-upstream-failure.yaml", nil),
	}
	if g.Auth != nil {
		logs = append(logs, b.fill("log-auth-unavailable.yaml", data{"Namespace": g.Envoy.Namespace}))
	}
	removed := removedFromClients(g)
	listenerSplices := []splice{
		{"access_log", sequence(logs...)},
		{"http_filters", sequence(filters...)},
		{"virtual_hosts", sequence(virtualHosts...)},
	}
	// A splice no $name takes is an error (fill), and the listener holds $tracing only with tracing and
	// $transport_socket only with tls.
	if g.Tracing != nil {
		listenerSplices = append(listenerSplices, splice{"tracing", b.tracing(g.Tracing)})
	}
	if g.TLS != nil {
		listenerSplices = append(listenerSplices, splice{"transport_socket", b.fill("transport-socket-tls.yaml",
			data{"Certificate": g.TLS.Certificate, "Key": g.TLS.Key, "ClientsCA": g.TLS.ClientsCA})})
	}
	listener := b.fill("listener.yaml", data{
		"Port":           g.Listen.Number,
		"RequestHeaders": requestHeaders(g.Limits.RequestHeaders),
		"Removed":        removed,
		"Auth":           g.Auth != nil,
		"Tracing":        g.Tracing != nil,
		"Downstream":     downstreamRemoved(g, removed),
		// Only connection takes the peer of the connection, so a Gateway built with the zero value renders 2.0's false.
		"RemoteAddress": g.ClientAddress == model.ClientConnection,
		"TLS":           g.TLS != nil,
		"RateLimit":     hasRateLimit(g),
	}, listenerSplices...)
	root := b.fill("bootstrap.yaml", data{"Admin": g.Admin, "Heap": g.Envoy.Heap, "Connections": g.Limits.Connections},
		splice{"listener", sequence(listener)}, splice{"clusters", sequence(clusters...)})
	if b.err != nil {
		return nil, b.err
	}
	return encode(root)
}

// lbPolicies names Envoy's lb_policy for each balance but round_robin, Envoy's default, which the cluster leaves
// unwritten so a 2.0 file's cluster stays as 2.0 wrote it.
var lbPolicies = map[string]string{"least_requests": "LEAST_REQUEST", "random": "RANDOM", "hash": "RING_HASH"}

// otelCluster names the cluster of the OpenTelemetry collector, which the tracer's grpc_service names too; jwksCluster
// the cluster of the keys URL, which the token filter's remote_jwks names too.
const (
	otelCluster = "otel_collector"
	jwksCluster = "jwks"
)

// cluster is the data of the cluster that carries one port of a service to its backends: clusterData with the
// service's own settings.
func cluster(g *model.Gateway, service model.Service, port model.ServicePort) data {
	addresses := make([]string, len(service.Addresses))
	for i, address := range service.Addresses {
		addresses[i] = address.Value
	}
	values := clusterData(g, service.Cluster(port.Protocol), addresses, port.Number, service.DNS, port.Protocol == model.GRPC)
	values["LBPolicy"] = lbPolicies[service.Balance.Value]
	values["Health"] = health(service, port.Protocol)
	values["Connections"] = g.Limits.Connections
	values["UpstreamIdle"] = seconds(g.Timeouts.UpstreamIdle)
	if service.Hash != nil {
		values["HashHeader"], values["HashClient"] = service.Hash.Header, service.Hash.Client
	}
	return values
}

// extraCluster is the data of a cluster that carries no service, such as the OpenTelemetry collector's: one backend at
// host and port, which the proxy looks up when dns, spoken as HTTP/2 when http2. A service's settings stay off it: no
// balance, hash, health check, connection limit or idle timeout.
func extraCluster(g *model.Gateway, name, host string, port int64, dns, http2 bool) data {
	return clusterData(g, name, []string{host}, port, dns, http2)
}

// keysCluster is the data of the cluster the token filter fetches the keys URL through: an extra cluster spoken as
// HTTP/1.1 over TLS, whose server must hold a certificate that chains to the CA bundle and names the URL's host. A name
// is also sent as the server name; an IP address is not, because RFC 6066 section 3 allows no IP address there, and it
// is matched as an address.
func keysCluster(g *model.Gateway) data {
	j := g.JWT
	values := extraCluster(g, jwksCluster, j.Host, j.Port, j.DNS, false)
	tls := data{"SNI": "", "CA": j.CA, "SANType": "IP_ADDRESS", "SAN": j.Host}
	if j.DNS {
		tls["SNI"], tls["SANType"] = j.Host, "DNS"
	}
	values["TLS"] = tls
	return values
}

// clusterData is the data of cluster.yaml for a cluster of addresses at port. It holds every key the fragment reads,
// each of a service's own settings with its zero value, which renders nothing, because fill runs every fragment with
// missingkey=error. A cluster that looks a name up takes dns.resolver when it is written; a STATIC cluster looks up no
// name, so it takes no resolver, and a resolver no cluster needs renders nothing.
func clusterData(g *model.Gateway, name string, addresses []string, port int64, dns, http2 bool) data {
	values := data{
		"Name":         name,
		"Addresses":    addresses,
		"DNS":          dns,
		"LBPolicy":     "",
		"Resolver":     nil,
		"HashHeader":   "",
		"HashClient":   false,
		"Health":       nil,
		"Port":         port,
		"HTTP2":        http2,
		"Connections":  nil,
		"UpstreamIdle": "",
		"TLS":          nil,
	}
	if dns && g.Resolver != nil {
		values["Resolver"] = data{"Address": g.Resolver.Address, "Port": g.Resolver.Port}
	}
	return values
}

// health is the data of a cluster's check, nil when the cluster gets none: an http cluster is checked when the
// service writes health.path, a grpc cluster when it writes health.grpc. Path is "" on a gRPC cluster, and Host, the
// service's host_header, is "" when not written.
func health(service model.Service, protocol model.Protocol) data {
	h := service.Health
	if h == nil || (protocol == model.HTTP && h.Path == nil) || (protocol == model.GRPC && h.GRPC == nil) {
		return nil
	}
	path := ""
	if protocol == model.HTTP {
		path = h.Path.Value
	}
	return data{
		"Timeout":   model.FormatSeconds(h.Timeout.Millis),
		"Interval":  model.FormatSeconds(h.Interval.Millis),
		"Healthy":   h.Healthy,
		"Unhealthy": h.Unhealthy,
		"Path":      path,
		"GRPC":      protocol == model.GRPC,
		"Host":      service.HostHeader,
	}
}

// routes is the route list every virtual host holds: the refused route (route-refused.yaml), then the plain routes in
// the order written, with the RPC routes, sorted by path, at the place of the rpc entry.
func (b *builder) routes(in Input) []*yaml.Node {
	g := in.Gateway
	// The refusal of a dot segment with a parameter comes first, so no route of the file takes such a path.
	routes := []*yaml.Node{b.fill("route-refused.yaml", nil)}
	for _, route := range g.Routes {
		if route.RPC != nil {
			for _, r := range in.RPC {
				routes = append(routes, b.fill("rpc-route.yaml", data{
					"Name":      r.Name,
					"Path":      r.Path(),
					"Auth":      g.Auth != nil,
					"Namespace": g.Envoy.Namespace,
					"Action":    r.Action,
					"Reports":   strings.Join(r.Reports, ","),
					"Bridge":    g.Envoy.ConnectBridge,
					"RateLimit": routeLimit(g, &route),
					"Decorator": decorator(g, r.Name),
				}, splice{"action", b.action(g, r.Target, model.GRPC, nil, route.RPC.Retries)}))
			}
			continue
		}
		service := g.Service(route.To.Value)
		routes = append(routes, b.fill("route.yaml", data{
			"Name":      route.Name.Value,
			"Match":     string(route.Match),
			"Value":     route.Value.Value,
			"Method":    route.Method,
			"Metadata":  g.Auth != nil && route.AuthOff == nil,
			"Namespace": g.Envoy.Namespace,
			// auth: off turns off each of the two filters the gateway has: the token filter and ext_authz.
			"AuthOff":   route.AuthOff != nil,
			"JWT":       g.JWT != nil,
			"Check":     g.Auth != nil,
			"RateLimit": routeLimit(g, &route),
			"Decorator": decorator(g, route.Name.Value),
		}, splice{"action", b.action(g, service, model.HTTP, route.Rewrite, route.Retries)}))
	}
	return routes
}

// decorator is the name of a route's span: the route's name with otel, "" otherwise. With OpenTelemetry Envoy names
// every span ingress unless the route names it (measured on Envoy 1.40.2). X-Ray keeps 2.0's routes, which name none.
func decorator(g *model.Gateway, route string) string {
	if g.Tracing == nil || g.Tracing.OTel == nil {
		return ""
	}
	return route
}

// rateLimitNamespace is the namespace of the route metadata that names a route's bucket, beside the gateway's own.
func rateLimitNamespace(namespace string) string {
	return namespace + ".rate_limit"
}

// limitOf is the limit of one entry of routes: the rpc entry's or the route's own, nil without one.
func limitOf(route *model.Route) *model.RateLimit {
	if route.RPC != nil {
		return route.RPC.RateLimit
	}
	return route.RateLimit
}

// bucketID names the bucket of one entry of routes: rpc for the rpc entry, the route's name otherwise. It is never the
// name of an Envoy route, which several rendered routes can share (an rpc entry's routes and a plain route may carry
// the same name), while the read rules keep each route's name unique and never rpc.
func bucketID(route *model.Route) string {
	if route.RPC != nil {
		return "rpc"
	}
	return route.Name.Value
}

// bucket is one token bucket of the rate limit filter: MaxTokens is requests + burst, and TokensPerFill requests, which
// Envoy adds over each FillInterval, the period.
type bucket struct {
	ID                       string
	ByClient                 bool
	MaxTokens, TokensPerFill int64
	FillInterval             string
}

// buckets is one bucket for each limited entry of routes, in the written order.
func buckets(g *model.Gateway) []bucket {
	var list []bucket
	for i := range g.Routes {
		if limit := limitOf(&g.Routes[i]); limit != nil {
			list = append(list, bucket{ID: bucketID(&g.Routes[i]), ByClient: limit.ByClient, MaxTokens: limit.Requests + limit.Burst,
				TokensPerFill: limit.Requests, FillInterval: model.FormatSeconds(limit.Per.Millis)})
		}
	}
	return list
}

// routeLimit is the data of the metadata that names a route's bucket, by the key the filter's rate_limits read for it
// (client or all), nil when the route has no limit.
func routeLimit(g *model.Gateway, route *model.Route) data {
	limit := limitOf(route)
	if limit == nil {
		return nil
	}
	by := "all"
	if limit.ByClient {
		by = "client"
	}
	return data{"Namespace": rateLimitNamespace(g.Envoy.Namespace), "By": by, "ID": bucketID(route)}
}

// action is the part of a route both kinds share: the cluster it goes to, the Host and path it rewrites, and how
// long and how often a request is tried.
func (b *builder) action(g *model.Gateway, service *model.Service, protocol model.Protocol, rewrite *model.Text,
	retries int64) *yaml.Node {
	var prefixRewrite string
	if rewrite != nil {
		prefixRewrite = rewrite.Value
	}
	return b.fill("route-action.yaml", data{
		"Cluster":       service.Cluster(protocol),
		"HostRewrite":   service.HostHeader,
		"PrefixRewrite": prefixRewrite,
		"Timeout":       seconds(g.Timeouts.Request),
		"IdleTimeout":   seconds(g.Timeouts.Idle),
		"Retries":       retries,
	})
}

// check is the ext_authz filter's data, nil without auth.ask. The read rules have made the auth service a declared
// service with an http port.
func check(g *model.Gateway) data {
	a := g.Auth
	if a == nil {
		return nil
	}
	service := g.Service(a.Service.Value)
	port, _ := service.Port(model.HTTP)
	return data{
		// JoinHostPort writes an IPv6 address in brackets, as a URI needs it. ext_authz never sends the uri, so the first
		// backend names it whatever the number of backends.
		"URI":            "http://" + net.JoinHostPort(service.Addresses[0].Value, strconv.FormatInt(port.Number, 10)) + a.Path,
		"Cluster":        service.Cluster(model.HTTP),
		"Path":           a.Path,
		"Timeout":        model.FormatSeconds(a.Timeout.Millis),
		"TimeoutMillis":  a.Timeout.Millis,
		"Enabled":        a.Enabled,
		"Allow":          a.Allow,
		"OnlyWithHeader": a.OnlyWithHeader,
		"Send":           a.Send,
		"Accept":         a.Accept,
		"SendRequest":    a.SendRequest,
	}
}

// jwt is the token filter's data, nil without auth.jwt. The authorization header carries the token after the Bearer
// scheme, and any other header the bare token.
func jwt(g *model.Gateway) data {
	j := g.JWT
	if j == nil {
		return nil
	}
	return data{
		"Issuer":    j.Issuer,
		"Audiences": j.Audiences,
		"File":      j.File,
		"URL":       j.URL,
		"Cluster":   jwksCluster,
		"Header":    j.Header,
		"Bearer":    j.Header == "authorization",
		"Optional":  j.Optional,
		"Claims":    j.Claims,
	}
}

// questionHeaders are the headers a route's question travels in, which ext_authz sends to the check.
var questionHeaders = []model.Header{{Name: "x-gateway-action"}, {Name: "x-gateway-reports"}}

// removedFromClients is the early header removal's list before Envoy's own mark: remove_from_clients in the order
// written, then, with auth.ask, the question headers and each accept name, then, with auth.jwt, each claims header,
// each that no entry before it covers. Only the gateway, the check and the token set those headers, so a client's copy
// is removed whether or not remove_from_clients lists it. A covered header adds nothing, so a file whose
// remove_from_clients covers them all gets no entry from here.
func removedFromClients(g *model.Gateway) []model.Header {
	var set []model.Header
	if g.Auth != nil {
		set = slices.Concat(questionHeaders, g.Auth.Accept)
	}
	if g.JWT != nil {
		for _, claim := range g.JWT.Claims {
			set = append(set, model.Header{Name: claim.Header})
		}
	}
	removed := slices.Clone(g.RemoveFromClients)
	for _, header := range set {
		if !slices.ContainsFunc(removed, func(entry model.Header) bool { return entry.Covers(header) }) {
			removed = append(removed, header)
		}
	}
	return removed
}

// requestHeaders is the connection manager's header limits, nil when the proxyfile sets none. The size pattern
// admits only whole KiB, MiB or GiB, so the byte count divides by 1024.
func requestHeaders(limits *model.RequestHeaders) data {
	if limits == nil {
		return nil
	}
	return data{"KiB": limits.Size.Bytes / 1024, "Count": limits.Count.Number}
}

// seconds writes an optional time as Envoy reads a duration, or "" when it is not written. none is 0s, which Envoy
// reads as no limit for every duration proxyfile writes from a time (route_components.proto, RouteAction's timeout
// and idle_timeout; protocol.proto, HttpProtocolOptions.idle_timeout).
func seconds(t *model.Time) string {
	if t == nil {
		return ""
	}
	return model.FormatSeconds(t.Millis)
}

// data is a fragment's template data: plain values, already formatted.
type data = map[string]any

// splice names the node a fragment's $name value is replaced by.
type splice struct {
	name string
	node *yaml.Node
}

// virtualHost is the data of one environment's virtual host. The RBAC principals and the CORS list take the
// environment's origins and patterns from the same lists, so CORS admits no origin RBAC refuses. RBAC also admits an
// origin on one of the environment's own hosts (SameOriginRegex), which the CORS list does not hold.
func virtualHost(environment origins.Environment, cors origins.CORS) data {
	sameOrigin := make([]string, len(environment.Hosts))
	for i, host := range environment.Hosts {
		sameOrigin[i] = origins.SameOriginRegex(host)
	}
	patterns := make([]string, len(environment.Patterns))
	for i, pattern := range environment.Patterns {
		patterns[i] = origins.PatternRegex(pattern)
	}
	return data{
		"Name":          environment.Name,
		"Hosts":         environment.Hosts,
		"SameOrigin":    sameOrigin,
		"Origins":       environment.Origins,
		"Patterns":      patterns,
		"AllowMethods":  cors.AllowMethods,
		"AllowHeaders":  cors.AllowHeaders,
		"ExposeHeaders": cors.ExposeHeaders,
		"MaxAge":        cors.MaxAge,
	}
}

// builder fills fragments and keeps the first error, so Generate reads in the order of the tree it builds.
type builder struct {
	err error
}

func (b *builder) fill(fragment string, values data, splices ...splice) *yaml.Node {
	if b.err != nil {
		return nil
	}
	node, err := fill(fragment, values, splices)
	if err != nil {
		b.err = fmt.Errorf("fragment %s: %w", fragment, err)
	}
	return node
}

// functions holds q, which writes a string as a double-quoted scalar, so no text from the input can change the YAML
// around it.
var functions = template.FuncMap{"q": scalar}

// scalar writes text as a YAML double-quoted scalar that go-yaml reads back as the same text. A JSON string is one
// (its escapes are all YAML escapes, YAML 1.2.2 section 5.7) except for characters JSON writes as they are and
// go-yaml v3.0.6 will not read inside quotes: DEL, the C1 controls, U+FFFE and U+FFFF, which its reader refuses
// (readerc.go, "control characters are not allowed"), and NEL, which it allows but scans as a line break
// (yamlprivateh.go, is_break), so a quoted NEL would read back as a space. Each of those is written as a \u escape.
func scalar(text string) string {
	var out strings.Builder
	for _, r := range quote.JSON(text) {
		if (r >= 0x7f && r <= 0x9f) || r == 0xfffe || r == 0xffff {
			fmt.Fprintf(&out, `\u%04x`, r)
			continue
		}
		out.WriteRune(r)
	}
	return out.String()
}

// fill executes a fragment's template with values, parses the result into a node and puts each splice's node in
// place of its $name. A $name with no splice, or a splice no $name uses, is an error.
func fill(fragment string, values data, splices []splice) (*yaml.Node, error) {
	source, err := fragments.ReadFile("fragments/" + fragment)
	if err != nil {
		return nil, err
	}
	tmpl, err := template.New(fragment).Option("missingkey=error").Funcs(functions).Parse(string(source))
	if err != nil {
		return nil, err
	}
	var text bytes.Buffer
	if err := tmpl.Execute(&text, values); err != nil {
		return nil, err
	}
	var document yaml.Node
	if err := yaml.Unmarshal(text.Bytes(), &document); err != nil {
		return nil, err
	}
	if len(document.Content) == 0 {
		return nil, errors.New("the fragment holds no YAML")
	}
	root := document.Content[0]
	tidy(root)
	used := make([]bool, len(splices))
	if err := replace(root, splices, used); err != nil {
		return nil, err
	}
	for i, s := range splices {
		if !used[i] {
			return nil, fmt.Errorf("no $%s takes the node given for it", s.name)
		}
	}
	return root, nil
}

// tidy readies a parsed fragment for splicing.
//
// It clears every comment. The comments explain a fragment to proxyfile's maintainers. go-yaml keeps a comment only
// near the data it is attached to (yaml.go, the Node type's documentation: "An effort is made ... to preserve
// comments near the data they describe"), so after splicing its place would depend on the splice.
//
// It marks the Lua script as a literal block, so the generated file shows it line by line, where q's quotes would put
// it on one line. Only the script: it is the one text with line breaks a fragment holds, and every other value stays
// in q's quotes, which read back as the same text whatever it holds. A literal block does not: go-yaml v3.0.6 writes
// one whose first line starts with a tab, and its reader refuses that tab as indentation (scannerc.go,
// yaml_parser_scan_block_scalar_breaks). The X-Ray sampling manifest, the other text with line breaks, is spliced in
// after tidy runs, already a literal block (tracing). It can be one: its first line starts with {, and every text in
// it is a JSON string of printable ASCII (the read rules' patterns for a rule's host, method and path), so it holds
// no tab.
func tidy(n *yaml.Node) {
	n.HeadComment, n.LineComment, n.FootComment = "", "", ""
	if n.Kind == yaml.ScalarNode && n.Value == connectStatus {
		n.Style = yaml.LiteralStyle
	}
	for _, child := range n.Content {
		tidy(child)
	}
}

// replace puts each splice's node in place of a plain scalar $name that is a mapping value, and marks the splice
// used. A quoted "$..." is text, never a place to splice.
func replace(n *yaml.Node, splices []splice, used []bool) error {
	for i, child := range n.Content {
		// A mapping's Content holds its keys and values in turn, so a value has an odd index.
		value := n.Kind == yaml.MappingNode && i%2 == 1
		if value && child.Kind == yaml.ScalarNode && child.Style == 0 && strings.HasPrefix(child.Value, "$") {
			j := slices.IndexFunc(splices, func(s splice) bool { return "$"+s.name == child.Value })
			if j < 0 {
				return fmt.Errorf("no node is given for %s", child.Value)
			}
			n.Content[i], used[j] = splices[j].node, true
			continue
		}
		if err := replace(child, splices, used); err != nil {
			return err
		}
	}
	return nil
}

// sequence is a block list of nodes. The emitter writes a list with no item as [] (emitterc.go,
// yaml_emitter_check_empty_sequence).
func sequence(items ...*yaml.Node) *yaml.Node {
	return &yaml.Node{Kind: yaml.SequenceNode, Tag: "!!seq", Content: items}
}

// encode writes the header line and the tree. Each node keeps the style its fragment wrote, or tidy gave it: a flow
// mapping or list stays on one line, because the emitter's width is unlimited by default (apic.go and emitterc.go,
// best_width), and a block stays a block.
func encode(root *yaml.Node) ([]byte, error) {
	var out bytes.Buffer
	out.WriteString(header)
	encoder := yaml.NewEncoder(&out)
	encoder.SetIndent(2)
	encoder.CompactSeqIndent()
	if err := encoder.Encode(root); err != nil {
		return nil, err
	}
	if err := encoder.Close(); err != nil {
		return nil, err
	}
	return out.Bytes(), nil
}

// downstreamHeaders are the headers Envoy strips from a client's request only on an edge request, which needs
// use_remote_address (conn_manager_utility.cc lines 275 and 354 to 359), so with client_address: forwarded, the
// listener's use_remote_address: false, a client's copy reaches the service, and the first reaches each segment as its
// downstream_cluster (http_tracer_impl.cc lines 169 to 170). They are removed with connection too, where Envoy strips
// them only from a request it counts as external.
var downstreamHeaders = []model.Header{{Name: "x-envoy-downstream-service-cluster"}, {Name: "x-envoy-downstream-service-node"}}

// decoratorHeader names a request's span with OpenTelemetry, so with otel a client's copy is removed: it would rename
// the span (measured on Envoy 1.40.2). It renames no X-Ray segment (measured on Envoy 1.40.2), so with xray it is left
// as 2.0 left it.
var decoratorHeader = model.Header{Name: "x-envoy-decorator-operation"}

// downstreamRemoved is the end of the early header removal: with tracing, each of downstreamHeaders, and with otel
// decoratorHeader after them, that no entry before it covers, the rule removedFromClients follows. Without tracing it
// is empty, so a proxyfile without the key gives 1.1's bytes.
func downstreamRemoved(g *model.Gateway, removed []model.Header) []string {
	if g.Tracing == nil {
		return nil
	}
	headers := downstreamHeaders
	if g.Tracing.OTel != nil {
		headers = slices.Concat(downstreamHeaders, []model.Header{decoratorHeader})
	}
	var names []string
	for _, header := range headers {
		if !slices.ContainsFunc(removed, func(entry model.Header) bool { return entry.Covers(header) }) {
			names = append(names, header.Name)
		}
	}
	return names
}

// tracing is the connection manager's tracing for the provider written, with X-Ray's manifest spliced in as a literal
// block when there is a sample.
func (b *builder) tracing(t *model.Tracing) *yaml.Node {
	var splices []splice
	if t.XRay != nil && t.XRay.Sample != nil {
		splices = append(splices, splice{"manifest", &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: manifest(t.XRay.Sample), Style: yaml.LiteralStyle}})
	}
	return b.fill("tracing.yaml", data{"PathInURL": t.PathInURL, "Tags": t.Tags, "XRay": t.XRay, "OTel": t.OTel,
		"Cluster": otelCluster}, splices...)
}

// manifest is the X-Ray sampling manifest: the default rule on the second line, then the rules in the written order,
// each after the first on its own line under the first's {, and one newline at the end. The manifest is text in the
// tree, so proxyfile writes it in one layout, and the same proxyfile gives the same bytes.
func manifest(s *model.Sample) string {
	var out strings.Builder
	fmt.Fprintf(&out, "{\"version\": 2,\n \"default\": {\"fixed_target\": %d, \"rate\": %s}", s.Default.First,
		fraction(s.Default.RatePercent))
	for i, rule := range s.Rules {
		if i == 0 {
			out.WriteString(",\n \"rules\": [")
		} else {
			// Under the first rule's {: the 11 characters of ` "rules": [`.
			out.WriteString(",\n           ")
		}
		fmt.Fprintf(&out, "{\"host\": %s, \"http_method\": %s, \"url_path\": %s, \"fixed_target\": %d, \"rate\": %s}",
			quote.JSON(rule.Host), quote.JSON(rule.Method), quote.JSON(rule.Path), rule.First, fraction(rule.RatePercent))
	}
	if len(s.Rules) > 0 {
		out.WriteString("]")
	}
	out.WriteString("}\n")
	return out.String()
}

// fraction writes a whole percentage as the shortest decimal of it over 100, in integer arithmetic, so no float
// rounding reaches the text: 0 is 0, 5 is 0.05, 50 is 0.5, 100 is 1. A rate is never 0.0 or 1.0, because a reader
// that keeps a number's type tells 0 from 0.0.
func fraction(percent int) string {
	switch percent {
	case 0:
		return "0"
	case 100:
		return "1"
	}
	return "0." + strings.TrimRight(fmt.Sprintf("%02d", percent), "0")
}
